job:
{runs-on: ubuntu-latest, steps: [{uses: actions/checkout@v3}, {uses: actions/setup-python@v4,
      with: {python-version: '${{ matrix.python-version }}'}}, {name: Install Poetry,
      run: 'curl -sSL https://install.python-poetry.org | python3 -

        '}, {name: Add Poetry to PATH, run: echo "$HOME/.local/bin" >> $GITHUB_PATH},
    {name: Set up Poetry cache, uses: actions/cache@v3, with: {key: '${{ runner.os
          }}-poetry-${{ hashFiles(''**/poetry.lock'') }}', path: ~/.cache/pypoetry,
        restore-keys: '${{ runner.os }}-poetry-

          '}}, {name: Install dependencies, run: poetry install}, {name: Build package,
      run: poetry build --format sdist}, {uses: actions/upload-artifact@v3, with: {
        name: package, path: dist/}}], strategy: {matrix: {python-version: ['3.10']}}}

{runs-on: ubuntu-latest, steps: [{name: Checkout, uses: actions/checkout@v4, with: {
        fetch-depth: 0}}, {name: Use Node.js, uses: actions/setup-node@v3, with: {
        cache: npm, node-version: 16}}, {name: Install dependencies, run: npm ci},
    {name: Run lint, run: npm run lint}, {name: Run type-check, run: npm run client-type-check},
    {name: Run tests, run: npm --prefix client run test}]}

{env: {ORT_LIB_LOCATION: '${{ github.workspace }}/lib/${{ matrix.target }}/onnxruntime'},
  runs-on: '${{ matrix.name }}', steps: [{if: matrix.name == 'ubuntu-20.04', uses: pierotofy/set-swap-space@v1.0,
      with: {swap-size-gb: 10}}, {name: Checkout code, uses: actions/checkout@v4,
      with: {token: '${{ secrets.GITHUB_TOKEN }}'}}, {name: Create LFS file list,
      run: git lfs ls-files --long | cut -d ' ' -f1 | sort > .lfs-assets-id}, {name: LFS
        Cache, uses: actions/cache@v3, with: {key: '${{ runner.os }}-lfs-${{ hashFiles(''.lfs-assets-id'')
          }}', path: .git/lfs/objects, restore-keys: '${{ runner.os }}-lfs-

          '}}, {name: Git LFS Pull, run: git lfs install && git lfs pull}, {name: Install
        Protoc, uses: arduino/setup-protoc@v2, with: {repo-token: '${{ secrets.GITHUB_TOKEN
          }}'}}, {if: matrix.target == 'x86_64-unknown-linux-gnu', run: sudo apt-get
        update && sudo apt-get install -y libgtk-3-dev webkit2gtk-4.0 libappindicator3-dev
        librsvg2-dev patchelf}, {name: Use Node.js, uses: actions/setup-node@v3, with: {
        cache: npm, node-version: 16}}, {name: Install app dependencies, run: npm
        ci}, {name: Install Rust stable, uses: dtolnay/rust-toolchain@stable, with: {
        target: '${{ matrix.target }}', toolchain: 1.73.0}}, {env: {analytics_fe_key: '${{
          secrets.ANALYTICS_FE_WRITE_KEY_PROD }}', analytics_key: '${{ secrets.ANALYTICS_BE_WRITE_KEY_PROD
          }}', sentry_dsn: '${{ secrets.SENTRY_DSN_BE }}', sentry_dsn_fe: '${{ secrets.SENTRY_DSN_FE
          }}'}, if: '${{ env.analytics_fe_key == '''' || env.sentry_dsn_fe == ''''
        || env.analytics_key == '''' || env.sentry_dsn == ''''}}', name: Check if
        keys exist, run: exit 1}, {name: Set environment, run: 'echo "{\"analytics_key\":\"${{
        secrets.ANALYTICS_BE_WRITE_KEY_PROD }}\",\"analytics_data_plane\":\"${{ secrets.ANALYTICS_DATA_PLANE_URL
        }}\",\"sentry_dsn_fe\":\"${{ secrets.SENTRY_DSN_FE }}\",\"sentry_dsn\":\"${{
        secrets.SENTRY_DSN_BE }}\",\"analytics_key_fe\":\"${{ secrets.ANALYTICS_FE_WRITE_KEY_PROD
        }}\",\"answer_api_url\":\"${{ secrets.ANSWER_API_URL }}\",\"cognito_userpool_id\":\"${{
        secrets.COGNITO_USERPOOL_ID }}\",\"cognito_client_id\":\"${{ secrets.COGNITO_CLIENT_ID
        }}\",\"cognito_auth_url\":\"${{ secrets.COGNITO_AUTH_URL }}\",\"cognito_mgmt_url\":\"${{
        secrets.COGNITO_MGMT_URL }}\",\"cognito_config_url\":\"${{ secrets.COGNITO_CONFIG_URL
        }}\"}" > apps/desktop/src-tauri/config/config.json'}, {name: Check environment
        is set, run: du -h apps/desktop/src-tauri/config/config.json}, {name: Set
        providerShortName in tauri.conf.json, uses: jossef/action-set-json-field@v2.1,
      with: {field: tauri.bundle.macOS.providerShortName, file: apps/desktop/src-tauri/tauri.conf.json,
        value: '${{ secrets.MAC_PROVIDER_SHORT_NAME }}'}}, {name: Set signingIdentity
        in tauri.conf.json, uses: jossef/action-set-json-field@v2.1, with: {field: tauri.bundle.macOS.signingIdentity,
        file: apps/desktop/src-tauri/tauri.conf.json, value: '${{ secrets.APPLE_SIGNING_IDENTITY
          }}'}}, {if: matrix.name == 'macos-11', name: Create Signing API Key, run: 'echo
        "${{ secrets.APPLE_API_KEY_CONTENT }}" > apiKey.p8'}, {if: matrix.target ==
        'aarch64-apple-darwin', name: Remove onnxruntime from aarch64-apple-darwin
        builds, uses: jossef/action-set-json-field@v2.1, with: {field: tauri.bundle.macOS.frameworks,
        file: apps/desktop/src-tauri/tauri.conf.json, parse_json: true, value: '[]'}},
    {id: release-version, name: get release version, run: echo "RELEASE_VERSION=$(cat
        apps/desktop/src-tauri/tauri.conf.json | jq '.package.version' | tr -d '"')"
        >> "$GITHUB_OUTPUT"}, {env: {APPLE_API_ISSUER: '${{ secrets.APPLE_API_ISSUER
          }}', APPLE_API_KEY: '${{ secrets.APPLE_API_KEY }}', APPLE_API_KEY_PATH: /Users/runner/work/bloop/bloop/apiKey.p8,
        APPLE_CERTIFICATE: '${{ secrets.APPLE_CERTIFICATE }}', APPLE_CERTIFICATE_PASSWORD: '${{
          secrets.APPLE_CERTIFICATE_PASSWORD }}', APPLE_SIGNING_IDENTITY: '${{ secrets.APPLE_SIGNING_IDENTITY
          }}', ENABLE_CODE_SIGNING: '${{ secrets.APPLE_CERTIFICATE }}', GITHUB_TOKEN: '${{
          secrets.GITHUB_TOKEN }}', NODE_OPTIONS: --max-old-space-size=4096, ORT_LIB_LOCATION: '${{
          github.workspace }}/lib/${{ matrix.target }}/onnxruntime', SENTRY_AUTH_TOKEN: '${{
          secrets.SENTRY_AUTH_TOKEN }}', SENTRY_RELEASE_VERSION: '${{ steps.release-version.outputs.RELEASE_VERSION
          }}', TAURI_BIN_PATH: apps/desktop/src-tauri/bin, TAURI_KEY_PASSWORD: '${{
          secrets.TAURI_KEY_PASSWORD }}', TAURI_PRIVATE_KEY: '${{ secrets.TAURI_PRIVATE_KEY
          }}'}, uses: tauri-apps/tauri-action@cb58ba3f65bd456ee564376585a8400bf0b71f47,
      with: {args: '-- --target "${{ matrix.target }}" -v'}}, {name: Upload artifacts,
      uses: actions/upload-artifact@v3, with: {name: '${{ matrix.target }}-app', path: 'target/${{
          matrix.target }}/release/bundle', retention-days: 5}}, {name: Setup Sentry
        CLI, uses: mathieu-bour/setup-sentry-cli@v1.3.0, with: {organization: '${{
          secrets.SENTRY_ORG }}', project: '${{ secrets.SENTRY_PROJECT }}', token: '${{
          secrets.SENTRY_AUTH_TOKEN }}', version: 2.21.2}}, {name: Create Sentry release,
      run: 'sentry-cli releases new "${{ steps.release-version.outputs.RELEASE_VERSION
        }}"

        sentry-cli releases set-commits "${{ steps.release-version.outputs.RELEASE_VERSION
        }}" --auto

        '}, {if: matrix.name == 'macos-11', name: (MacOS) Upload source maps to Sentry,
      run: 'sentry-cli debug-files upload \

        --log-level debug \

        --include-sources \

        target/${{ matrix.target }}/release/bloop.dSYM

        '}, {if: matrix.name == 'macos-11', name: Rename tar.gz in macos, run: 'new_filename="bloop_${{
        steps.release-version.outputs.RELEASE_VERSION }}_$(echo ${{ matrix.target
        }} | cut -d ''-'' -f 1).app.tar.gz"

        mv "target/${{ matrix.target }}/release/bundle/macos/bloop.app.tar.gz" "target/${{
        matrix.target }}/release/bundle/macos/${new_filename}"

        '}, {name: List files, run: 'ls -R target/${{ matrix.target }}/release/bundle'},
    {name: Generate Changelog, run: 'release_version="${{ steps.release-version.outputs.RELEASE_VERSION
        }}"

        sed "s/VERSION/${release_version}/g" release_description_template.txt > new_description.txt

        cat new_description.txt

        '}, {if: 'startsWith(github.ref, ''refs/tags/v'')', name: Upload release assets,
      uses: softprops/action-gh-release@v1, with: {files: 'target/${{ matrix.target
          }}/release/bundle/deb/*.deb

          target/${{ matrix.target }}/release/bundle/appimage/*.AppImage

          target/${{ matrix.target }}/release/bundle/appimage/*.tar.gz

          target/${{ matrix.target }}/release/bundle/dmg/*.dmg

          target/${{ matrix.target }}/release/bundle/macos/*.tar.gz

          '}}], strategy: {fail-fast: false, matrix: {include: [{name: ubuntu-20.04,
          target: x86_64-unknown-linux-gnu}, {name: macos-11, target: x86_64-apple-darwin},
        {name: macos-11, target: aarch64-apple-darwin}], target: [x86_64-unknown-linux-gnu,
        x86_64-apple-darwin, aarch64-apple-darwin]}}}

{secrets: {awsAccountID: '${{ secrets.AWS_ACCOUNT_ID }}', awsRegion: '${{ secrets.AWS_REGION
      }}', build-args: 'SENTRY_AUTH_TOKEN=${{ secrets.SENTRY_AUTH_TOKEN }}

      SENTRY_RELEASE_VERSION=${{ github.sha }}

      ', slackBuildWebhook: '${{ secrets.SLACK_BUILD_WEBHOOK }}'}, uses: BloopAI/workflows/.github/workflows/build-container.yml@main,
  with: {repository: bloop, runner: ubuntu-latest, tag: 'build-${{ github.sha }}'}}

{secrets: {awsAccountID: '${{ secrets.AWS_ACCOUNT_ID }}', awsRegion: '${{ secrets.AWS_REGION
      }}', build-args: 'SENTRY_AUTH_TOKEN=${{ secrets.SENTRY_AUTH_TOKEN }}

      SENTRY_RELEASE_VERSION=${{ github.event.release.tag_name }}

      ', slackBuildWebhook: '${{ secrets.SLACK_BUILD_WEBHOOK }}'}, uses: BloopAI/workflows/.github/workflows/build-container.yml@main,
  with: {repository: bloop, runner: ubuntu-latest, tag: '${{ github.event.release.tag_name
      }}'}}

{if: 'github.event.issue.pull_request && contains(github.event.comment.body, ''/build'')',
  name: Validate user is the member of BloopAI organization, outputs: {is-member: '${{
      steps.membership.outputs.is-member }}'}, runs-on: ubuntu-latest, steps: [{env: {
        ACTOR: '${{ github.triggering_actor }}'}, id: membership, name: Validation,
      run: "members=$(curl -L \\\n  -H \"Accept: application/vnd.github+json\" \\\n\
        \  -H \"Authorization: Bearer ${{ secrets.BLOOP_DEVOPS_PAT}}\"\\\n  -H \"\
        X-GitHub-Api-Version: 2022-11-28\" \\\n  https://api.github.com/orgs/BloopAI/members\
        \ | jq -r \".[] .login\")\nfor member in $(echo ${members}); do \n  if [[\
        \ $member = $ACTOR ]]; then \n    echo \"is-member=true\" >> $GITHUB_OUTPUT\n\
        \  fi\ndone\n"}]}

{if: 'github.event.issue.pull_request && contains(github.event.comment.body, ''/build'')
    && needs.permissions.outputs.is-member == ''true''', name: Run container build
    on comment, needs: [permissions], outputs: {ref: '${{ steps.comment-branch.outputs.head_ref
      }}', tag: 'build-${{ steps.comment-branch.outputs.head_sha }}'}, runs-on: ubuntu-latest,
  steps: [{id: comment-branch, name: Get PR branch, uses: xt0rted/pull-request-comment-branch@v1},
    {name: Checkout PR branch, uses: actions/checkout@v4, with: {ref: '${{ steps.comment-branch.outputs.head_ref
          }}'}}]}

{if: needs.permissions.outputs.is-member == 'true', needs: [permissions, build_tag],
  secrets: {awsAccountID: '${{ secrets.AWS_ACCOUNT_ID }}', awsRegion: '${{ secrets.AWS_REGION
      }}', build-args: 'SENTRY_AUTH_TOKEN=${{ secrets.SENTRY_AUTH_TOKEN }}

      SENTRY_RELEASE_VERSION=${{ needs.build_tag.outputs.tag }}

      ', slackBuildWebhook: '${{ secrets.SLACK_BUILD_WEBHOOK }}'}, uses: BloopAI/workflows/.github/workflows/build-container.yml@main,
  with: {repository: bloop, runner: ubuntu-latest, tag: '${{ needs.build_tag.outputs.tag
      }}'}}

{if: always() && needs.permissions.outputs.is-member == 'true', name: Report status
    of the build, needs: [permissions, build_tag, build_and_push], runs-on: ubuntu-latest,
  steps: [{id: pr, name: pr, run: 'PR_NUMBER=$(echo $GITHUB_REF | awk ''BEGIN { FS
        = "/" } ; { print $3 }'')

        echo "number=${PR_NUMBER}" >> ${GITHUB_OUTPUT}

        '}, {if: '${{ contains(needs.*.result, ''failure'') }}', name: Comment failure
        build, uses: thollander/actions-comment-pull-request@v2, with: {message: ':red_circle:
          Bloop container with `${{ needs.build_tag.outputs.tag }}` tag failed!

          :link: ${{ github.server_url }}/${{ github.repository }}/actions/runs/${{
          github.run_id }}

          ', pr_number: '${{ steps.pr.outputs.number }}'}}, {if: '${{ !contains(needs.*.result,
        ''failure'') }}', name: Comment success build, uses: thollander/actions-comment-pull-request@v2,
      with: {message: ':green_circle: Bloop container with `${{ needs.build_tag.outputs.tag
          }}` tag is ready!

          :link: ${{ github.server_url }}/${{ github.repository }}/actions/runs/${{
          github.run_id }}

          ', pr_number: '${{ steps.pr.outputs.number }}'}}]}

{name: lint, runs-on: ubuntu-latest, steps: [{uses: actions/checkout@v4}, {uses: actions/setup-go@v5,
      with: {cache-dependency-path: wren-launcher/go.sum, go-version: '1.24'}}, {
      name: golangci-lint, uses: golangci/golangci-lint-action@v8, with: {version: v2.3.1,
        working-directory: wren-launcher}}]}

{needs: [build-image], runs-on: ubuntu-latest, steps: [{name: Download digests, uses: actions/download-artifact@v4,
      with: {merge-multiple: true, path: /tmp/digests, pattern: digests-*}}, {name: Set
        up Docker Buildx, uses: docker/setup-buildx-action@v3}, {id: meta, name: Docker
        meta, uses: docker/metadata-action@v5, with: {images: '${{ env.WREN_AI_SERVICE_IMAGE
          }}', tags: 'type=raw,${{ needs.build-image.outputs.tag_name }}

          type=raw,nightly

          '}}, {name: Login to GitHub Container Registry, uses: docker/login-action@v3,
      with: {password: '${{ secrets.GITHUB_TOKEN }}', registry: ghcr.io, username: '${{
          github.actor }}'}}, {name: Create manifest list and push, run: "TAGS=$(echo\
        \ \"${{ steps.meta.outputs.tags }}\" | awk '{printf \"--tag %s \", $0}')\n\
        docker buildx imagetools create $(jq -cr '.tags | map(\"-t \" + .) | join(\"\
        \ \")' <<< \"$DOCKER_METADATA_OUTPUT_JSON\") \\\n  $(printf '${{ env.WREN_AI_SERVICE_IMAGE\
        \ }}@sha256:%s ' *) \\\n  $TAGS\n", working-directory: /tmp/digests}]}

{needs: [build-image], runs-on: ubuntu-latest, steps: [{name: Download digests, uses: actions/download-artifact@v4,
      with: {merge-multiple: true, path: /tmp/digests, pattern: digests-*}}, {name: Set
        up Docker Buildx, uses: docker/setup-buildx-action@v3}, {id: meta, name: Docker
        meta, uses: docker/metadata-action@v5, with: {images: '${{ env.WREN_AI_SERVICE_IMAGE
          }}', tags: 'type=raw,${{ github.event.inputs.version }}

          type=raw,latest

          '}}, {name: Login to GitHub Container Registry, uses: docker/login-action@v3,
      with: {password: '${{ secrets.GITHUB_TOKEN }}', registry: ghcr.io, username: '${{
          github.actor }}'}}, {name: Create manifest list and push, run: "TAGS=$(echo\
        \ \"${{ steps.meta.outputs.tags }}\" | awk '{printf \"--tag %s \", $0}')\n\
        docker buildx imagetools create $(jq -cr '.tags | map(\"-t \" + .) | join(\"\
        \ \")' <<< \"$DOCKER_METADATA_OUTPUT_JSON\") \\\n  $(printf '${{ env.WREN_AI_SERVICE_IMAGE\
        \ }}@sha256:%s ' *) \\\n  $TAGS\n", working-directory: /tmp/digests}]}

{if: '${{ github.event.label.name == ''ci/ui''}}', runs-on: ubuntu-latest, steps: [
    {uses: actions/checkout@v4}, {name: Set up Node.js, uses: actions/setup-node@v2,
      with: {node-version: '18'}}, {id: yarn-cache-dir-path, name: Get yarn cache
        directory path, run: 'echo "::set-output name=dir::$(yarn cache dir)"'}, {
      id: yarn-cache, uses: actions/cache@v2, with: {key: '${{ runner.os }}-yarn-${{
          hashFiles(''**/yarn.lock'') }}', path: '${{ steps.yarn-cache-dir-path.outputs.dir
          }}

          ', restore-keys: '${{ runner.os }}-yarn-

          '}}, {continue-on-error: true, if: '${{ steps.yarn-cache.cache-hit != ''true''
        }}', name: List the state of node modules, run: yarn list}, {name: Install
        dependencies, run: yarn}, {name: Run tests, run: yarn test}]}

{if: '${{ github.event.label.name == ''ci/ui'' }}', runs-on: ubuntu-latest, steps: [
    {uses: actions/checkout@v3}, {name: Set up Node.js, uses: actions/setup-node@v2,
      with: {node-version: '18'}}, {id: yarn-cache-dir-path, name: Get yarn cache
        directory path, run: 'echo "::set-output name=dir::$(yarn cache dir)"'}, {
      id: yarn-cache, uses: actions/cache@v2, with: {key: '${{ runner.os }}-yarn-${{
          hashFiles(''**/yarn.lock'') }}', path: '${{ steps.yarn-cache-dir-path.outputs.dir
          }}

          ', restore-keys: '${{ runner.os }}-yarn-

          '}}, {continue-on-error: true, if: '${{ steps.yarn-cache.outputs.cache-hit
        != ''true'' }}', name: List the state of node modules, run: yarn list}, {
      name: Install Node.js dependencies, run: yarn install}, {name: Run lint, run: yarn
        lint}]}

{needs: [build-image], runs-on: ubuntu-latest, steps: [{name: Download digests, uses: actions/download-artifact@v4,
      with: {merge-multiple: true, path: /tmp/digests, pattern: digests-*}}, {name: Set
        up Docker Buildx, uses: docker/setup-buildx-action@v3}, {id: meta, name: Docker
        meta, uses: docker/metadata-action@v5, with: {images: '${{ env.WREN_UI_IMAGE
          }}', tags: '${{ needs.build-image.outputs.tag_name }}

          '}}, {name: Login to GitHub Container Registry, uses: docker/login-action@v3,
      with: {password: '${{ secrets.GITHUB_TOKEN }}', registry: ghcr.io, username: '${{
          github.actor }}'}}, {name: Create manifest list and push, run: "TAGS=$(echo\
        \ \"${{ steps.meta.outputs.tags }}\" | awk '{printf \"--tag %s \", $0}')\n\
        docker buildx imagetools create $(jq -cr '.tags | map(\"-t \" + .) | join(\"\
        \ \")' <<< \"$DOCKER_METADATA_OUTPUT_JSON\") \\\n  $(printf '${{ env.WREN_UI_IMAGE\
        \ }}@sha256:%s ' *) \\\n  $TAGS\n", working-directory: /tmp/digests}]}

{permissions: {pull-requests: write}, runs-on: ubuntu-latest, steps: [{name: Checkout
        code, uses: actions/checkout@v3, with: {fetch-depth: 0}}, {id: changed-files,
      name: Get changed files, uses: tj-actions/changed-files@v46}, {name: Tag PR
        based on changed files and title, uses: actions/github-script@v6, with: {
        github-token: '${{ secrets.GITHUB_TOKEN }}', script: "const changedFiles =\
          \ '${{ steps.changed-files.outputs.all_changed_files }}'.split(' ');
const\
          \ labels = new Set();

// Define label colors
const labelColors = {
\
          \  'wren-ui': 'f29513',        // Orange
  'launcher': 'f29513',      \
          \ // Orange (same as wren-ui)
  'wren-ai-service': 'f29513', // Orange\
          \ (same as wren-ui)
  'deployment': '0075ca',     // Blue
  'ai-env-changed':\
          \ 'd73a4a',  // Red
  'ui-env-changed': 'd73a4a'   // Red
};


// Check\
          \ for files in specific directories
for (const file of changedFiles) {
\
          \  if (file.startsWith('wren-ui/src/')) {
    labels.add('wren-ui');
\
          \  } else if (file.startsWith('deployment/')) {
    labels.add('deployment');
\
          \  } else if (file.startsWith('wren-launcher/')) {
    labels.add('launcher');
\
          \  } else if (file.startsWith('wren-ai-service/')) {
    labels.add('wren-ai-service');
\
          \  } 
  if (file.startsWith('docker/') && file.includes('.example')) {
\
          \    labels.add('ai-env-changed'); 
  }
  if (file.startsWith('wren-ui/src/apollo/server/config.ts'))\
          \ {
    labels.add('ui-env-changed');
  }
}

// Extract milestone from\
          \ PR title
const prTitle = context.payload.pull_request.title;
const milestoneMatch\
          \ = prTitle.match(/\(milestone:\s*([^)]+)\)/i);

if (milestoneMatch\
          \ && milestoneMatch[1]) {
  const milestone = milestoneMatch[1].trim();
\
          \  if (milestone) {
    labels.add(milestone);
    console.log(`Found\
          \ milestone in PR title: ${milestone}`);
  }
}

// Append env changed\
          \ label to PR title
if (labels.has('ai-env-changed')) {
  // check if\
          \ pr title contains "ai-env-changed"
  if (!prTitle.includes('ai-env-changed'))\
          \ {
    const newTitle = `${prTitle} (ai-env-changed)`;
    await github.rest.issues.update({
\
          \      owner: context.repo.owner,
      repo: context.repo.repo,
    \
          \  issue_number: context.issue.number,
      title: newTitle
    });
\
          \  }
}

if (labels.has('ui-env-changed')) {
  // check if pr title contains\
          \ "ui-env-changed"
  if (!prTitle.includes('ui-env-changed')) {
   \
          \ const newTitle = `${prTitle} (ui-env-changed)`;
    await github.rest.issues.update({
\
          \      owner: context.repo.owner,
      repo: context.repo.repo,
    \
          \  issue_number: context.issue.number,
      title: newTitle
    });
\
          \  }
}

if (labels.size > 0) {
  // Create or update labels with colors
\
          \  for (const label of labels) {
    try {
      // Try to create the\
          \ label with color
      if (labelColors[label]) {
        await github.rest.issues.createLabel({
\
          \          owner: context.repo.owner,
          repo: context.repo.repo,
\
          \          name: label,
          color: labelColors[label]
        });
\
          \      }
    } catch (error) {
      // Label already exists, update its\
          \ color if needed
      if (labelColors[label]) {
        try {
    \
          \      await github.rest.issues.updateLabel({
            owner: context.repo.owner,
\
          \            repo: context.repo.repo,
            name: label,
      \
          \      color: labelColors[label]
          });
        } catch (updateError)\
          \ {
          console.log(`Could not update color for label ${label}: ${updateError.message}`);
\
          \        }
      }
    }
  }

  // Add labels to PR
  await github.rest.issues.addLabels({
\
          \    owner: context.repo.owner,
    repo: context.repo.repo,
    issue_number:\
          \ context.issue.number,
    labels: Array.from(labels)
  });

  console.log(`Added\
          \ labels: ${Array.from(labels).join(', ')}`);
} else {
  console.log('No\
          \ matching directories or milestone found');
}
"}}]}

{needs: [build-image], runs-on: ubuntu-latest, steps: [{name: Download digests, uses: actions/download-artifact@v4,
      with: {merge-multiple: true, path: /tmp/digests, pattern: digests-*}}, {name: Set
        up Docker Buildx, uses: docker/setup-buildx-action@v3}, {id: meta, name: Docker
        meta, uses: docker/metadata-action@v5, with: {images: '${{ env.WREN_UI_IMAGE
          }}', tags: '${{ github.event.inputs.version }}

          '}}, {name: Login to GitHub Container Registry, uses: docker/login-action@v3,
      with: {password: '${{ secrets.GITHUB_TOKEN }}', registry: ghcr.io, username: '${{
