    prNumber = fs.readFileSync('/tmp/pr_number.txt',\
          \ 'utf8').trim();
  } else {
    branchName = fs.readFileSync('/tmp/branch_name.txt',\
          \ 'utf8').trim();
  }
} catch (error) {
  console.error('Error reading\
          \ file:', error);
}


try {
  if (!success){
    // Read result_explanation\
          \ from JSON file for failed resolution
    const outputFilePath = path.resolve('/tmp/output/output.jsonl');
\
          \    if (fs.existsSync(outputFilePath)) {
      const outputContent = fs.readFileSync(outputFilePath,\
          \ 'utf8');
      const jsonLines = outputContent.split('\n').filter(line\
          \ => line.trim() !== '');

      if (jsonLines.length > 0) {
       \
          \ // First entry in JSON lines has the key 'result_explanation'
      \
          \  const firstEntry = JSON.parse(jsonLines[0]);
        resultExplanation\
          \ = firstEntry.result_explanation || '';
      }
    }
  }
} catch (error){
\
          \  console.error('Error reading file:', error);
}

// Check "success"\
          \ log from resolver output
if (success && prNumber) {
  github.rest.issues.createComment({
\
          \    issue_number: issueNumber,
    owner: context.repo.owner,
    repo:\
          \ context.repo.repo,
    body: `A potential fix has been generated and\
          \ a draft PR #${prNumber} has been created. Please review the changes.`
\
          \  });
  process.env.AGENT_RESPONDED = 'true';
} else if (!success &&\
          \ branchName) {
  let commentBody = `An attempt was made to automatically\
          \ fix this issue, but it was unsuccessful. A branch named '${branchName}'\
          \ has been created with the attempted changes. You can view the branch [here](https://github.com/${context.repo.owner}/${context.repo.repo}/tree/${branchName}).\
          \ Manual intervention may be required.`;

  if (resultExplanation) {
\
          \    commentBody += `\n\nAdditional details about the failure:\n${resultExplanation}`;
\
          \  }

  github.rest.issues.createComment({
    issue_number: issueNumber,
\
          \    owner: context.repo.owner,
    repo: context.repo.repo,
    body:\
          \ commentBody
  });
  process.env.AGENT_RESPONDED = 'true';
}
"}}, {
      env: {ISSUE_NUMBER: '${{ env.ISSUE_NUMBER }}'}, if: '${{ env.AGENT_RESPONDED
        == ''false'' }}', name: Fallback Error Comment, uses: actions/github-script@v9,
      with: {github-token: '${{ secrets.PAT_TOKEN || github.token }}', script: "const\
          \ issueNumber = process.env.ISSUE_NUMBER;

github.rest.issues.createComment({
\
          \  issue_number: issueNumber,
  owner: context.repo.owner,
  repo: context.repo.repo,
\
          \  body: `The workflow to fix this issue encountered an error. Please check\
          \ the [workflow logs](https://github.com/${context.repo.owner}/${context.repo.repo}/actions/runs/${context.runId})\
          \ for more information.`
});
"}}]}

