{runs-on: ubuntu-latest, steps: [{id: check_status, if: github.event_name == 'issue_comment'
        && github.event.issue.pull_request, name: Check comment permissions and deployment
        status, uses: actions/github-script@v8, with: {script: "const commentBody\
          \ = context.payload.comment.body.trim();
const commentUser = context.payload.comment.user.login;
\
          const prAuthor = context.payload.issue.user.login;
const authorAssociation\
          \ = context.payload.comment.author_association;

// Check permissions
\
          const hasPermission = (
  authorAssociation === 'OWNER' ||
  authorAssociation\
          \ === 'MEMBER' ||
  authorAssociation === 'COLLABORATOR'
);

core.setOutput('comment_body',\
          \ commentBody);
core.setOutput('has_permission', hasPermission);

if\
          \ (!hasPermission && (commentBody === '!deploy' || commentBody === '!undeploy'))\
          \ {
  core.setOutput('permission_denied', 'true');
  return;
}

if\
          \ (commentBody !== '!deploy' && commentBody !== '!undeploy') {
  return;
\
          }

// Process deploy command
if (commentBody === '!deploy') {
  core.setOutput('should_deploy',\
          \ 'true');
}
// Process undeploy command
else if (commentBody === '!undeploy')\
          \ {
  core.setOutput('should_undeploy', 'true');
}
"}}, {if: steps.check_status.outputs.permission_denied
        == 'true', name: Post permission denied comment, uses: actions/github-script@v8,
      with: {script: "await github.rest.issues.createComment({
  owner: context.repo.owner,
\
          \  repo: context.repo.repo,
  issue_number: context.issue.number,
  body:\
          \ `❌ **Permission denied**: Only the repository owners, members, or\
          \ collaborators can use deployment commands.`
});
"}}, {id: pr_details,
      if: steps.check_status.outputs.should_deploy == 'true' || steps.check_status.outputs.should_undeploy
        == 'true', name: Get PR details for deployment, uses: actions/github-script@v8,
      with: {script: "const pr = await github.rest.pulls.get({
  owner: context.repo.owner,
\
          \  repo: context.repo.repo,
  pull_number: context.issue.number
});
\
          core.setOutput('pr_number', pr.data.number);
core.setOutput('pr_title',\
          \ pr.data.title);
core.setOutput('pr_state', pr.data.state);
"}}, {if: steps.check_status.outputs.should_deploy
        == 'true', name: Dispatch Deploy Event, uses: peter-evans/repository-dispatch@v4,
      with: {client-payload: "{
  "action": "deploy",
  "pr_number": "${{\
          \ steps.pr_details.outputs.pr_number }}",
  "pr_title": "${{ steps.pr_details.outputs.pr_title\
          \ }}",
  "pr_state": "${{ steps.pr_details.outputs.pr_state }}",
\
          \  "repo": "${{ github.repository }}"
}
", event-type: pr-event, repository: Significant-Gravitas/AutoGPT_cloud_infrastructure,
        token: '${{ secrets.DISPATCH_TOKEN }}'}}, {if: steps.check_status.outputs.should_deploy
        == 'true', name: Post deploy success comment, uses: actions/github-script@v8,
      with: {script: "await github.rest.issues.createComment({
  owner: context.repo.owner,
\
          \  repo: context.repo.repo,
  issue_number: context.issue.number,
  body:\
          \ `\U0001F680 **Deploying PR #${{ steps.pr_details.outputs.pr_number }}**\
          \ to development environment...`
});
"}}, {if: steps.check_status.outputs.should_undeploy
        == 'true', name: Dispatch Undeploy Event (from comment), uses: peter-evans/repository-dispatch@v4,
      with: {client-payload: "{
  "action": "undeploy",
  "pr_number": "\
          ${{ steps.pr_details.outputs.pr_number }}",
  "pr_title": "${{ steps.pr_details.outputs.pr_title\
          \ }}",
  "pr_state": "${{ steps.pr_details.outputs.pr_state }}",
\
          \  "repo": "${{ github.repository }}"
}
", event-type: pr-event, repository: Significant-Gravitas/AutoGPT_cloud_infrastructure,
        token: '${{ secrets.DISPATCH_TOKEN }}'}}, {if: steps.check_status.outputs.should_undeploy
        == 'true', name: Post undeploy success comment, uses: actions/github-script@v8,
      with: {script: "await github.rest.issues.createComment({
  owner: context.repo.owner,
\
          \  repo: context.repo.repo,
  issue_number: context.issue.number,
  body:\
          \ `\U0001F5D1️ **Undeploying PR #${{ steps.pr_details.outputs.pr_number\
          \ }}** from development environment...`
});
"}}, {id: check_pr_close,
      if: github.event_name == 'pull_request' && github.event.action == 'closed',
      name: Check deployment status on PR close, uses: actions/github-script@v8, with: {
        script: "const comments = await github.rest.issues.listComments({
  owner:\
          \ context.repo.owner,
  repo: context.repo.repo,
  issue_number: context.issue.number
\
          });

let lastDeployIndex = -1;
let lastUndeployIndex = -1;

comments.data.forEach((comment,\
          \ index) => {
  if (comment.body.trim() === '!deploy') {
    lastDeployIndex\
          \ = index;
  } else if (comment.body.trim() === '!undeploy') {
    lastUndeployIndex\
          \ = index;
  }
});

// Should undeploy if there's a !deploy without\
          \ a subsequent !undeploy
const shouldUndeploy = lastDeployIndex !== -1\
          \ && lastDeployIndex > lastUndeployIndex;
core.setOutput('should_undeploy',\
