{name: Trust Check, outputs: {is-trusted: '${{ steps.check-trust.outputs.is-trusted
      }}'}, permissions: {actions: read, issues: read, pull-requests: read}, runs-on: ubuntu-latest,
  steps: [{id: check-trust, name: Check if PR is trusted, uses: actions/github-script@v7,
      with: {script: "const trustedAssociations = ['OWNER', 'MEMBER', 'COLLABORATOR'];
\

if (!context.payload.pull_request) {
  if (context.eventName === 'workflow_dispatch')\
          \ {
    console.log('workflow_dispatch event - assuming trusted (manual\
          \ trigger)');
    core.setOutput('is-trusted', true);
    return;
  }
\
          \  console.log('No pull request context found');
  core.setOutput('is-trusted',\
          \ false);
  return;
}

const owner = context.repo.owner;
const repo\
          \ = context.repo.repo;

// Fetch fresh PR data - payload labels may be\
          \ stale on re-runs
const { data: pr } = await github.rest.pulls.get({
\
          \  owner,
  repo,
  pull_number: context.payload.pull_request.number,
\
          });

const prNumber = pr.number;
const headSha = pr.head.sha;

async\
          \ function hasWriteAccess(username) {
  try {
    const { data: permission\
          \ } = await github.rest.repos.getCollaboratorPermissionLevel({
      owner,
\
          \      repo,
      username,
    });
    return ['admin', 'maintain',\
          \ 'write'].includes(permission.permission);
  } catch (e) {
    console.log(`Permission\
          \ check failed for ${username}: ${e.message}`);
    return false;
  }
\
          }

console.log(`PR #${prNumber} by ${pr.user.login} (${pr.author_association})`);
\

// Check 1: Is the author a trusted contributor?
if (trustedAssociations.includes(pr.author_association))\
          \ {
  console.log(`Author has trusted association: ${pr.author_association}`);
\
          \  core.setOutput('is-trusted', true);
  return;
}

// Check 2: Verify\
          \ write access via API (author_association can be unreliable)
if (await\
          \ hasWriteAccess(pr.user.login)) {
  console.log(`Author has write access`);
\
          \  core.setOutput('is-trusted', true);
  return;
}

// Check 3: Was\
          \ 'run-ci' label added AFTER this SHA was pushed by someone with write access?
\
          // This enables re-runs triggered by the run-ci.yml workflow
// NOTE: We\
          \ use workflow run created_at instead of commit timestamp because
// git\
          \ commit timestamps can be arbitrarily backdated by attackers
if (pr.labels?.some(l\
          \ => l.name === 'run-ci')) {
  // Skip stale check if this is a re-run\
          \ (run_attempt > 1)
  // Re-runs are explicitly triggered by maintainers
\
          \  const runAttempt = parseInt(process.env.GITHUB_RUN_ATTEMPT || '1', 10);
\
          \  if (runAttempt > 1) {
    console.log(`Re-run detected (attempt ${runAttempt}),\
          \ trusting existing 'run-ci' label`);
    core.setOutput('is-trusted',\
          \ true);
    return;
  }

  const events = await github.paginate(github.rest.issues.listEvents,\
          \ {
    owner,
    repo,
    issue_number: prNumber,
    per_page: 100,
\
          \  });

  const labelEvent = events
    .filter(e => e.event === 'labeled'\
          \ && e.label?.name === 'run-ci')
    .sort((a, b) => new Date(b.created_at)\
          \ - new Date(a.created_at))[0];

  if (labelEvent) {
    // Get workflow\
          \ runs to find when this SHA was first pushed
    const runs = await github.paginate(github.rest.actions.listWorkflowRuns,\
          \ {
      owner,
      repo,
      workflow_id: 'pr.yml',
      head_sha:\
          \ headSha,
      per_page: 100,
    });

    // Filter runs to this\
          \ PR (in case same SHA exists in multiple PRs)
    const matchingRuns =\
          \ runs.filter(run =>
      !run.pull_requests?.length || run.pull_requests.some(p\
          \ => p.number === prNumber)
    );

    if (matchingRuns.length > 0)\
          \ {
      const labelTime = new Date(labelEvent.created_at);
      //\
          \ Use the oldest run's created_at as the push time
      const originalRun\
          \ = matchingRuns[matchingRuns.length - 1];
      const pushTime = new Date(originalRun.created_at);
\

      if (labelTime > pushTime) {
        const adder = labelEvent.actor.login;
\
          \        if (await hasWriteAccess(adder)) {
          console.log(`Approved\
          \ via 'run-ci' label added by ${adder} after push (label: ${labelTime.toISOString()},\
          \ push: ${pushTime.toISOString()})`);
          core.setOutput('is-trusted',\
          \ true);
          return;
        }
        console.log(`Label 'run-ci'\
          \ added by ${adder} (no write access)`);
      } else {
        console.log(`Label\
          \ 'run-ci' is stale (label: ${labelTime.toISOString()}, push: ${pushTime.toISOString()})`);
\
          \      }
    } else {
      console.log('No workflow runs found for this\
          \ SHA - cannot validate label timing');
    }
  }
}

console.log('External\
          \ contribution requires "run-ci" label from a maintainer');
core.setOutput('is-trusted',\
          \ false);
"}}]}

{if: needs.trust-check.outputs.is-trusted == 'true', name: Prepare, needs: [trust-check],
  outputs: {commit-sha: '${{ steps.get_sha.outputs.commit-sha }}', db-cache-hit: '${{
      steps.cache-db-check.outputs.cache-hit }}', has-api-v2-changes: '${{ steps.filter-inclusions.outputs.has-api-v2-changes
      }}', has-files-requiring-all-checks: '${{ steps.filter-exclusions.outputs.has-files-requiring-all-checks
      }}', has-prisma-changes: '${{ steps.filter-inclusions.outputs.has-prisma-changes
      }}', run-e2e: '${{ steps.check-if-pr-has-label.outputs.run-e2e == ''true'' }}'},
  permissions: {pull-requests: read}, runs-on: ubuntu-latest, steps: [{uses: actions/checkout@v4,
      with: {sparse-checkout: .github}}, {uses: ./.github/actions/cache-checkout},
    {id: cache-db-key, name: Generate DB cache key, uses: ./.github/actions/cache-db-key},
    {id: cache-db-check, name: Check DB cache (lookup-only), uses: actions/cache/restore@v4,
      with: {key: '${{ steps.cache-db-key.outputs.key }}', lookup-only: true, path: backups/backup.sql}},
    {id: filter-exclusions, name: Check for files requiring all checks (with exclusions),
      uses: dorny/paths-filter@v3, with: {filters: "has-files-requiring-all-checks:
\
          \  - '**'
  - '!.vscode/**'
  - '!**/*.md'
  - '!**/*.mdx'
  - '!.github/CODEOWNERS'
