has-prisma-changes:
\
          \  - "packages/prisma/schema.prisma"
  - "packages/prisma/migrations/**"\

"}}, {id: get_sha, name: Get Latest Commit SHA, run: 'echo "commit-sha=$(git
        rev-parse HEAD)" >> $GITHUB_OUTPUT

        '}, {id: check-if-pr-has-label, name: Check if PR exists with ready-for-e2e
        label for this SHA, uses: actions/github-script@v7, with: {script: "let labels\
          \ = [];
let prNumber = null;

if (context.payload.pull_request) {
 \
          \ prNumber = context.payload.pull_request.number;
} else {
  try {
 \
          \   const sha = '${{ steps.get_sha.outputs.commit-sha }}';
    console.log('sha',\
          \ sha);
    const { data: prs } = await github.rest.repos.listPullRequestsAssociatedWithCommit({
\
          \      owner: context.repo.owner,
      repo: context.repo.repo,
    \
          \  commit_sha: sha
    });

    if (prs.length === 0) {
      core.setOutput('run-e2e',\
          \ false);
      console.log(`No pull requests found for commit SHA ${sha}`);
\
          \      return;
    }

    prNumber = prs[0].number;
  }
  catch (e)\
          \ {
    core.setOutput('run-e2e', false);
    console.log(e);
    return;
\
          \  }
}

