{needs: build, runs-on: '${{ matrix.os }}', steps: [{name: Check-out repository, uses: actions/checkout@v6},
    {name: Use Node.js from .nvmrc, uses: actions/setup-node@v6, with: {node-version-file: .nvmrc}},
    {name: Cache core node_modules, uses: actions/cache@v5, with: {key: '${{ runner.os
          }}-node-${{ hashFiles(''core/package-lock.json'') }}', path: core/node_modules}},
    {name: Cache binary node_modules, uses: actions/cache@v5, with: {key: '${{ runner.os
          }}-node-${{ hashFiles(''binary/package-lock.json'') }}', path: binary/node_modules}},
    {name: Install Core Dependencies, run: 'cd ../../core

        npm ci

        '}, {name: Install Binary Dependencies, run: 'cd ../../binary

        npm ci

        '}, {name: Download binary artifact, uses: actions/download-artifact@v8, with: {
        name: 'continue-binary-${{ matrix.platform }}-${{ matrix.arch }}', path: './binary/bin/${{
          matrix.platform }}-${{ matrix.arch }}/'}}, {if: '${{ matrix.platform }}
        != ''win32''', name: Set execute permissions, run: 'cd ../../binary/bin/${{
        matrix.platform }}-${{ matrix.arch }}

        chmod +x continue-binary

        chmod +x build/Release/node_sqlite3.node

        chmod +x index.node

        '}, {name: Run binary tests, run: 'cd ../../binary

        npm run test

        '}, {if: '${{ always() }}', name: Upload logs, uses: actions/upload-artifact@v7,
      with: {name: 'core-logs-${{ matrix.platform }}-${{ matrix.arch }}', path: ~/.continue/logs/core.log}}],
  strategy: {matrix: {include: [{arch: x64, npm_config_arch: x64, os: windows-latest,
          platform: win32}, {arch: x64, npm_config_arch: x64, os: ubuntu-latest, platform: linux},
        {arch: x64, npm_config_arch: x64, os: macos-12, platform: darwin}, {arch: arm64,
          npm_config_arch: arm64, os: macos-latest, platform: darwin}]}}}

