\
        - Ensuring the fixes don't break other functionality

Please start by examining\
        \ the failing tests and their error messages, then proceed with the necessary\
        \ fixes.
PROMPT_EOF

echo "Starting Continue CLI remote session for test\
        \ fixes..."
echo "Prompt content:"
cat /tmp/fix_tests_prompt.txt

\
        # Start remote session and capture JSON output
SESSION_OUTPUT=$(cat /tmp/fix_tests_prompt.txt\
