          \ > 800) ||
      title.match(/(major|milestone|launch)/)) {
    return\
          \ 'tier 1';
  }

  // Tier 2: Important features (500+ lines changed,\
          \ or 10+ files, or standard feat)
  if (totalChanges > 500 || changedFiles\
          \ > 10 || prefix === 'feat') {
    return 'tier 2';
  }

  // Tier\
          \ 3: Smaller improvements
  return 'tier 3';
}

const tier = determineTier(pr);
