    await github.rest.issues.addLabels({
\
          \      owner: context.repo.owner,
      repo: context.repo.repo,
    \
          \  issue_number: issue.number,
      labels: [label],
    });
    labelApplied\
          \ = true;
    break;
  } catch (e) {
    console.log(`Label '${label}'\
          \ unavailable or failed to apply, trying next`);
  }
}
if (!labelApplied)\
          \ {
  console.log('No close label could be applied; continuing with close/lock');
\
          }

await github.rest.issues.update({
  owner: context.repo.owner,
 \
          \ repo: context.repo.repo,
  issue_number: issue.number,
  state: 'closed',
\
          });

await github.rest.issues.lock({
  owner: context.repo.owner,
 \
          \ repo: context.repo.repo,
  issue_number: issue.number,
  lock_reason:\
          \ 'spam',
});

console.log(`Issue #${issue.number} closed and locked`);
"}}]}

{permissions: {pull-requests: write}, runs-on: ubuntu-latest, steps: [{uses: actions/checkout@v4,
      with: {fetch-depth: 0}}, {id: check-uv-lock, name: Check for uv.lock changes,
      run: "if git diff --name-only ${{ github.event.pull_request.base.sha }} ${{\
        \ github.event.pull_request.head.sha }} | grep -q "uv.lock"; then
  echo\
        \ "uv_lock_changed=true" >> $GITHUB_OUTPUT
else
  echo "uv_lock_changed=false"\
        \ >> $GITHUB_OUTPUT
fi
"}, {id: check-pyproject, name: Check for pyproject.toml
        changes, run: "if git diff --name-only ${{ github.event.pull_request.base.sha\
        \ }} ${{ github.event.pull_request.head.sha }} | grep -q "pyproject.toml"\
        ; then
  echo "pyproject_changed=true" >> $GITHUB_OUTPUT
else
  echo\
        \ "pyproject_changed=false" >> $GITHUB_OUTPUT
fi
"}, {if: steps.check-uv-lock.outputs.uv_lock_changed
        == 'true' || steps.check-pyproject.outputs.pyproject_changed == 'true', name: Create
        PR comment, uses: actions/github-script@v7, with: {script: "const uvLockChanged\
          \ = ${{ steps.check-uv-lock.outputs.uv_lock_changed }};
const pyprojectChanged\
          \ = ${{ steps.check-pyproject.outputs.pyproject_changed }};

let message\
          \ = '\U0001F4E6 Dependencies Alert:\n\n';

if (uvLockChanged && pyprojectChanged)\
          \ {
  message += '- Both `uv.lock` and `pyproject.toml` have been modified\\
          n';
} else if (uvLockChanged) {
  message += '- `uv.lock` has been modified\\
          n';
} else if (pyprojectChanged) {
  message += '- `pyproject.toml` has\
          \ been modified\n';
}

message += '\nPlease review these changes carefully\
          \ to ensure they are intended (cc @sarahwooders @cpacker).';

github.rest.issues.createComment({
\
          \  issue_number: context.issue.number,
  owner: context.repo.owner,
 \
          \ repo: context.repo.repo,
  body: message
});
"}}]}

